@@ -0,0 +1,90 @@
+import { readdir, readFile } from "node:fs/promises";
+import { join } from "node:path";
+import * as z from "zod";
+import { REVIEW_SIZES, SOURCE_KINDS } from "../../src/schema/types.ts";
+
+const nonemptyString = z.string().min(1);
+
+const pathSet = z.array(nonemptyString).min(1);
+
+const expectSchema = z
+  .strictObject({
+    why: z.enum(["present", "absent"]).optional(),
+    parts: z
+      .strictObject({
+        min: z.number().int().nonnegative(),
+        max: z.number().int().nonnegative(),
+      })
+      .optional(),
+    size: z.array(z.enum(REVIEW_SIZES)).min(1).optional(),
+    sourceKinds: z.array(z.enum(SOURCE_KINDS)).min(1).optional(),
+    mechanicalPaths: pathSet.optional(),
+    together: z.array(pathSet).optional(),
+    apart: z.array(z.tuple([nonemptyString, nonemptyString])).optional(),
+    claims: z.array(nonemptyString).min(1).optional(),
+  })
+  .optional();
+
+const caseSchema = z.strictObject({
+  id: nonemptyString,
+  repo: nonemptyString,
+  pr: z.number().int().positive(),
+  base: nonemptyString,
+  head: nonemptyString,
+  tags: z.array(nonemptyString).default([]),
+  expect: expectSchema,
+});
+
+export type EvalCase = z.infer<typeof caseSchema>;
+export type EvalExpect = NonNullable<EvalCase["expect"]>;
+
+export function parseEvalCase(value: unknown): EvalCase {
+  return caseSchema.parse(value);
+}
+
+export function parseEvalCaseJson(text: string): EvalCase {
+  let value: unknown;
+  try {
+    value = JSON.parse(text);
+  } catch {
+    throw new Error("case.json is not valid JSON");
+  }
+  return parseEvalCase(value);
+}
+
+export async function loadEvalCase(dir: string): Promise<EvalCase> {
+  const loaded = parseEvalCaseJson(await readFile(join(dir, "case.json"), "utf8"));
+  const folder = dir.replace(/\\/g, "/").split("/").pop();
+  if (folder !== loaded.id) {
+    throw new Error(`case id "${loaded.id}" does not match folder "${folder}"`);
+  }
+  return loaded;
+}
+
+export async function listEvalCases(casesDir: string): Promise<{ dir: string; spec: EvalCase }[]> {
+  const names = await readdir(casesDir, { withFileTypes: true });
+  const loaded: { dir: string; spec: EvalCase }[] = [];
+  for (const entry of names.sort((a, b) => a.name.localeCompare(b.name))) {
+    if (!entry.isDirectory()) {
+      continue;
+    }
+    const dir = join(casesDir, entry.name);
+    loaded.push({ dir, spec: await loadEvalCase(dir) });
+  }
+  return loaded;
+}
+
+export function selectEvalCases(
+  cases: { dir: string; spec: EvalCase }[],
+  opts: { ids?: string[]; tag?: string },
+): { dir: string; spec: EvalCase }[] {
+  return cases.filter(({ spec }) => {
+    if (opts.ids !== undefined && opts.ids.length > 0 && !opts.ids.includes(spec.id)) {
+      return false;
+    }
+    if (opts.tag !== undefined && !spec.tags.includes(opts.tag)) {
+      return false;
+    }
+    return true;
+  });
+}

diff --git a/scripts/eval/args.ts b/scripts/eval/args.ts
new file mode 100644
index 0000000..e1f5a51
--- /dev/null
+++ b/scripts/eval/args.ts
@@ -0,0 +1,137 @@
+import { DEFAULT_GRADER_MODEL, DEFAULT_PRODUCER_MODEL } from "./constants.ts";
+
+export const EVAL_USAGE = `Usage: pnpm eval -- [options]
+
+Grade Comprehende reviews. An isolated producer follows the next skill. Deterministic checks and two read-only graders then score the result. LLM findings do not change the exit code.
+
+Options:
+  --case <id>             Run this case (repeatable)
+  --tag <tag>             Run cases with this tag
+  --baseline <dir>        Print deltas against a previous eval/runs/<stamp>
+  --json                  Also print summary.json to stdout
+  --producer-model <id>   Default ${DEFAULT_PRODUCER_MODEL}
+  --grader-model <id>     Default ${DEFAULT_GRADER_MODEL}
+  --sandbox               Enable local sandboxOptions
+  -h, --help
+
+Needs CURSOR_API_KEY. Writes eval/runs/<stamp>/. Exit 1 only when a deterministic check fails.
+`;
+
+export const ADD_CASE_USAGE = `Usage: pnpm eval:add -- --pr <github pr url>
+
+Fetch a pull request and write eval/cases/<repo>-<n>/ with frozen sources and empty expect.
+
+Options:
+  --pr <url>    GitHub pull request URL
+  --id <id>     Case folder name (default: <repo>-<n>)
+  -h, --help
+`;
+
+export type EvalRunRequest =
+  | { kind: "help" }
+  | { kind: "error"; message: string }
+  | {
+      kind: "run";
+      ids: string[];
+      tag?: string;
+      baseline?: string;
+      json: boolean;
+      producerModel: string;
+      graderModel: string;
+      sandbox: boolean;
+    };
+
+export type AddCaseRequest =
+  | { kind: "help" }
+  | { kind: "error"; message: string }
+  | { kind: "add"; prUrl: string; id?: string };
+
+export function parseEvalArgv(argv: string[]): EvalRunRequest {
+  const args = argv[0] === "--" ? argv.slice(1) : [...argv];
+  if (args.includes("-h") || args.includes("--help")) {
+    return { kind: "help" };
+  }
+  try {
+    const ids: string[] = [];
+    let tag: string | undefined;
+    let baseline: string | undefined;
+    let producerModel = DEFAULT_PRODUCER_MODEL;
+    let graderModel = DEFAULT_GRADER_MODEL;
+    let json = false;
+    let sandbox = false;
+    for (let i = 0; i < args.length; i += 1) {
+      const arg = args[i];
+      if (arg === undefined) {
+        continue;
+      }
+      if (arg === "--json") {
+        json = true;
+        continue;
+      }
+      if (arg === "--sandbox") {
+        sandbox = true;
+        continue;
+      }
+      if (arg === "--case" || arg === "--tag" || arg === "--baseline" || arg === "--producer-model" || arg === "--grader-model") {
+        const value = args[i + 1];
+        if (value === undefined || value.startsWith("-")) {
+          throw new Error(`${arg} requires a value`);
+        }
+        i += 1;
+        if (arg === "--case") {
+          ids.push(value);
+        } else if (arg === "--tag") {
+          tag = value;
+        } else if (arg === "--baseline") {
+          baseline = value;
+        } else if (arg === "--producer-model") {
+          producerModel = value;
+        } else {
+          graderModel = value;
+        }
+        continue;
+      }
+      throw new Error(`Unknown option: ${arg}`);
+    }
+    return { kind: "run", ids, tag, baseline, json, producerModel, graderModel, sandbox };
+  } catch (error) {
+    return { kind: "error", message: error instanceof Error ? error.message : String(error) };
+  }
+}
+
+export function parseAddCaseArgv(argv: string[]): AddCaseRequest {
+  const args = argv[0] === "--" ? argv.slice(1) : [...argv];
+  if (args.length === 0 || args.includes("-h") || args.includes("--help")) {
+    return { kind: "help" };
+  }
+  try {
+    let prUrl: string | undefined;
+    let id: string | undefined;
+    for (let i = 0; i < args.length; i += 1) {
+      const arg = args[i];
+      if (arg === undefined) {
+        continue;
+      }
+      if (arg === "--pr" || arg === "--id") {
+        const value = args[i + 1];
+        if (value === undefined || value.startsWith("-")) {
+          throw new Error(`${arg} requires a value`);
+        }
+        i += 1;
+        if (arg === "--pr") {
+          prUrl = value;
+        } else {
+          id = value;
+        }
+        continue;
+      }
+      throw new Error(`Unknown option: ${arg}`);
+    }
+    if (prUrl === undefined) {
+      throw new Error("--pr is required");
+    }
+    return { kind: "add", prUrl, id };
+  } catch (error) {
+    return { kind: "error", message: error instanceof Error ? error.message : String(error) };
+  }
+}

